insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000048001', '20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000222', 'multiple_choice', 'easy', 'published', 'Em um esboço tridimensional preparado para uma aula, Dados os pontos $A=(1,1,2)$ e $B=(3,2,3)$, encontre o vetor que parte de A e chega a B.') on conflict (id) do update set subject_id = excluded.subject_id, source_id = excluded.source_id, kind = excluded.kind, difficulty = excluded.difficulty, publication_status = excluded.publication_status, statement_markdown = excluded.statement_markdown;
