insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000480011', '40000000-0000-4000-8000-000000048001', 'Faça primeiro um pequeno registro das grandezas conhecidas e daquilo que a pergunta realmente pede.', 1), ('60000000-0000-4000-8000-000000480012', '40000000-0000-4000-8000-000000048001', 'O vetor de A até B é obtido fazendo ponto final menos ponto inicial.', 2), ('60000000-0000-4000-8000-000000480013', '40000000-0000-4000-8000-000000048001', 'Subtraia separadamente as coordenadas x, y e z.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048001', '$AB=(2,1,1)$.', 'Trate as coordenadas como informações de posição: alinhar cada eixo antes de operar evita conclusões visuais enganosas. A representação por coordenadas permite executar a operação componente a componente, sempre preservando a ordem dos eixos. A conferência substitui o resultado na relação original e evita trocas de sinal ou de posição. A alternativa A coincide com a relação obtida; a alternativa B ($(-2,-1,-1)$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000480011', '40000000-0000-4000-8000-000000048001', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000480012', '40000000-0000-4000-8000-000000048001', 'Organize a subtração', '$AB=B-A.$', 2), ('70000000-0000-4000-8000-000000480013', '40000000-0000-4000-8000-000000048001', 'Calcule as componentes', '$AB=(3,2,3)-(1,1,2).$', 3), ('70000000-0000-4000-8000-000000480014', '40000000-0000-4000-8000-000000048001', 'Confira o sentido', '$A+AB=(3,2,3)=B$, portanto o sentido está correto.', 4), ('70000000-0000-4000-8000-000000480015', '40000000-0000-4000-8000-000000048001', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000048002', '20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000222', 'multiple_choice', 'easy', 'published', 'Uma equipe de modelagem precisa conferir o cálculo abaixo. Dados os pontos $A=(3,-1,4)$ e $B=(5,4,7)$, encontre o vetor que parte de A e chega a B.') on conflict (id) do update set subject_id = excluded.subject_id, source_id = excluded.source_id, kind = excluded.kind, difficulty = excluded.difficulty, publication_status = excluded.publication_status, statement_markdown = excluded.statement_markdown;
