insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000480021', '40000000-0000-4000-8000-000000048002', 'Escreva a relação matemática antes de substituir os valores; isso torna sinais e denominadores mais visíveis.', 1), ('60000000-0000-4000-8000-000000480022', '40000000-0000-4000-8000-000000048002', 'O vetor de A até B é obtido fazendo ponto final menos ponto inicial.', 2), ('60000000-0000-4000-8000-000000480023', '40000000-0000-4000-8000-000000048002', 'Subtraia separadamente as coordenadas x, y e z.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048002', '$AB=(2,5,3)$.', 'Uma boa conferência separa a ideia geométrica da conta numérica e testa o resultado na relação inicial. A representação por coordenadas permite executar a operação componente a componente, sempre preservando a ordem dos eixos. A conferência substitui o resultado na relação original e evita trocas de sinal ou de posição. A alternativa A coincide com a relação obtida; a alternativa B ($(-2,-5,-3)$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000480021', '40000000-0000-4000-8000-000000048002', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000480022', '40000000-0000-4000-8000-000000048002', 'Organize a subtração', '$AB=B-A.$', 2), ('70000000-0000-4000-8000-000000480023', '40000000-0000-4000-8000-000000048002', 'Calcule as componentes', '$AB=(5,4,7)-(3,-1,4).$', 3), ('70000000-0000-4000-8000-000000480024', '40000000-0000-4000-8000-000000048002', 'Confira o sentido', '$A+AB=(5,4,7)=B$, portanto o sentido está correto.', 4), ('70000000-0000-4000-8000-000000480025', '40000000-0000-4000-8000-000000048002', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
