insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048003', '$AB=(2,9,5)$.', 'O resultado deve respeitar tanto a definição algébrica quanto a interpretação geométrica do objeto em três dimensões. A representação por coordenadas permite executar a operação componente a componente, sempre preservando a ordem dos eixos. A conferência substitui o resultado na relação original e evita trocas de sinal ou de posição. A alternativa A coincide com a relação obtida; a alternativa B ($(-2,-9,-5)$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000480031', '40000000-0000-4000-8000-000000048003', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000480032', '40000000-0000-4000-8000-000000048003', 'Organize a subtração', '$AB=B-A.$', 2), ('70000000-0000-4000-8000-000000480033', '40000000-0000-4000-8000-000000048003', 'Calcule as componentes', '$AB=(7,6,11)-(5,-3,6).$', 3), ('70000000-0000-4000-8000-000000480034', '40000000-0000-4000-8000-000000048003', 'Confira o sentido', '$A+AB=(7,6,11)=B$, portanto o sentido está correto.', 4), ('70000000-0000-4000-8000-000000480035', '40000000-0000-4000-8000-000000048003', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
