insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048012', '$2u-v=(5,-1,-4)$.', 'Uma boa conferência separa a ideia geométrica da conta numérica e testa o resultado na relação inicial. A representação por coordenadas permite executar a operação componente a componente, sempre preservando a ordem dos eixos. A conferência substitui o resultado na relação original e evita trocas de sinal ou de posição. A alternativa A coincide com a relação obtida; a alternativa B ($(7,5,0)$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
