insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048021', '$M=(3,1,2)$.', 'Trate as coordenadas como informações de posição: alinhar cada eixo antes de operar evita conclusões visuais enganosas. A representação por coordenadas permite executar a operação componente a componente, sempre preservando a ordem dos eixos. A conferência substitui o resultado na relação original e evita trocas de sinal ou de posição. A alternativa A coincide com a relação obtida; a alternativa B ($(6,2,4)$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000480211', '40000000-0000-4000-8000-000000048021', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000480212', '40000000-0000-4000-8000-000000048021', 'Use a fórmula', 'Some as coordenadas dos extremos na mesma posição e divida cada soma por 2.', 2), ('70000000-0000-4000-8000-000000480213', '40000000-0000-4000-8000-000000048021', 'Calcule as médias', '$M=(3,1,2).$', 3), ('70000000-0000-4000-8000-000000480214', '40000000-0000-4000-8000-000000048021', 'Confira a simetria', 'Os vetores de M até os dois extremos têm mesmo módulo e sentidos opostos.', 4), ('70000000-0000-4000-8000-000000480215', '40000000-0000-4000-8000-000000048021', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
