insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000480221', '40000000-0000-4000-8000-000000048022', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000480222', '40000000-0000-4000-8000-000000048022', 'Use a fórmula', 'Some as coordenadas dos extremos na mesma posição e divida cada soma por 2.', 2), ('70000000-0000-4000-8000-000000480223', '40000000-0000-4000-8000-000000048022', 'Calcule as médias', '$M=(5,1,4).$', 3), ('70000000-0000-4000-8000-000000480224', '40000000-0000-4000-8000-000000048022', 'Confira a simetria', 'Os vetores de M até os dois extremos têm mesmo módulo e sentidos opostos.', 4), ('70000000-0000-4000-8000-000000480225', '40000000-0000-4000-8000-000000048022', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
