insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000480331', '40000000-0000-4000-8000-000000048033', 'Ao final, pergunte se o sinal, a direção ou a dimensão do resultado fazem sentido para a situação.', 1), ('60000000-0000-4000-8000-000000480332', '40000000-0000-4000-8000-000000048033', 'Um versor tem módulo 1 e o mesmo sentido do vetor original.', 2), ('60000000-0000-4000-8000-000000480333', '40000000-0000-4000-8000-000000048033', 'Divida todas as componentes pelo módulo de u.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048033', '$(3/5,4/5,0)$.', 'O resultado deve respeitar tanto a definição algébrica quanto a interpretação geométrica do objeto em três dimensões. O cálculo preserva a ordem das componentes e distingue o vetor de seu módulo e de sua direção. A verificação recompõe a definição utilizada, confirmando o resultado numérico e sua interpretação geométrica. A alternativa A coincide com a relação obtida; a alternativa B ($(4/5,3/5,0)$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
