insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000480491', '40000000-0000-4000-8000-000000048049', 'Não tente calcular tudo de uma vez: destaque primeiro a propriedade que caracteriza o problema.', 1), ('60000000-0000-4000-8000-000000480492', '40000000-0000-4000-8000-000000048049', 'Compare componentes correspondentes não nulas.', 2), ('60000000-0000-4000-8000-000000480493', '40000000-0000-4000-8000-000000048049', 'O mesmo fator precisa funcionar nas três coordenadas.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048049', '$k=9$.', 'A notação compacta não substitui o raciocínio: identificar o tipo de objeto é o passo que determina qual fórmula usar. O cálculo preserva a ordem das componentes e distingue o vetor de seu módulo e de sua direção. A verificação recompõe a definição utilizada, confirmando o resultado numérico e sua interpretação geométrica. A alternativa A coincide com a relação obtida; a alternativa B ($k=7$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000480491', '40000000-0000-4000-8000-000000048049', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000480492', '40000000-0000-4000-8000-000000048049', 'Compare uma componente', '$63=k7.$', 2), ('70000000-0000-4000-8000-000000480493', '40000000-0000-4000-8000-000000048049', 'Isole o escalar', '$k=9.$', 3), ('70000000-0000-4000-8000-000000480494', '40000000-0000-4000-8000-000000048049', 'Verifique', 'As outras duas componentes recebem exatamente o mesmo fator.', 4), ('70000000-0000-4000-8000-000000480495', '40000000-0000-4000-8000-000000048049', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000048050', '20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000222', 'multiple_choice', 'medium', 'published', 'Para validar um resultado de laboratório de geometria analítica, resolva: encontre de forma justificada k em $v=ku$, com $u=(9,18,-9)$ e $v=(99,198,-99)$.') on conflict (id) do update set subject_id = excluded.subject_id, source_id = excluded.source_id, kind = excluded.kind, difficulty = excluded.difficulty, publication_status = excluded.publication_status, statement_markdown = excluded.statement_markdown;
